import { useEffect, useState } from "react";
import { getChildren, getAttendance, addAttendance } from "../api/api";

function AdminDashboard() {
  const [children, setChildren] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [childId, setChildId] = useState("");
  const [checkIn, setCheckIn] = useState("");
  const [checkOut, setCheckOut] = useState("");
  const [date, setDate] = useState("");

  useEffect(() => {
    getChildren().then(res => setChildren(res)).catch(err => console.log(err));
    getAttendance().then(res => setAttendance(res)).catch(err => console.log(err));
  }, []);

  const handleSubmit = () => {
    if (!childId || !date) {
      alert("Select a child and date");
      return;
    }

    addAttendance({ child_id: childId, check_in: checkIn, check_out: checkOut, date })
      .then(() => {
        alert("Attendance saved");
        setCheckIn("");
        setCheckOut("");
        setDate("");
      })
      .catch(err => console.log(err));
  };

  const today = new Date().toISOString().slice(0, 10);
  const todayRecords = attendance.filter(record => record.date === today);

  return (
    <div>
      <h2>Admin Dashboard</h2>
      <section style={{ marginBottom: "24px" }}>
        <h3>Attendance Check In / Check Out</h3>
        <div style={{ display: "grid", gap: "12px", maxWidth: "420px" }}>
          <select value={childId} onChange={e => setChildId(e.target.value)}>
            <option value="">Select Child</option>
            {children.map(child => (
              <option key={child.id} value={child.id}>{child.name}</option>
            ))}
          </select>
          <input type="date" value={date} onChange={e => setDate(e.target.value)} />
          <input type="time" value={checkIn} onChange={e => setCheckIn(e.target.value)} placeholder="Check In" />
          <input type="time" value={checkOut} onChange={e => setCheckOut(e.target.value)} placeholder="Check Out" />
          <button onClick={handleSubmit}>Save Attendance</button>
        </div>
      </section>

      <section>
        <h3>Today&apos;s Attendance</h3>
        {todayRecords.length === 0 ? (
          <p>No attendance recorded for {today}.</p>
        ) : (
          <ul>
            {todayRecords.map(record => (
              <li key={record.id}>
                {record.name} — In: {record.check_in || "—"}, Out: {record.check_out || "—"}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

export default AdminDashboard;
